package app.yoru.vk;

import android.app.*;
import android.content.*;
import android.os.*;
import android.text.*;
import android.view.*;
import android.view.inputmethod.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.Future;

public final class MainActivity extends Activity {
    private VkApp app;
    private LinearLayout root,body;
    private TextView status,more;
    private EditText catalogInput,vkInput;
    private GridView grid;
    private String screen="catalog",catalogQuery="",videoQuery="";
    private int catalogPage=1,season=1,episode=1,ticket;
    private boolean loading;
    private String loadedCatalogQuery="";
    private String seasonDraft="1",episodeDraft="1",voiceDraft="";
    private Models.Anime current;
    private final ArrayList<Models.Anime> catalog=new ArrayList<>();
    private Future<?> work;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable autoSearch=()->loadCatalog(true);

    @Override public void onCreate(Bundle state){super.onCreate(state);app=(VkApp)getApplication();if(state!=null)catalogQuery=state.getString("catalogQuery","");showCatalog();loadCatalog(true);}
    @Override protected void onSaveInstanceState(Bundle out){out.putString("catalogQuery",catalogQuery);super.onSaveInstanceState(out);}
    private void cancel(){ticket++;loading=false;handler.removeCallbacks(autoSearch);if(work!=null)work.cancel(true);}
    private void shell(String title,Runnable back){root=Ui.column(this);Ui.base(this,root);LinearLayout top=Ui.row(this);top.setPadding(Ui.dp(this,16),Ui.dp(this,10),Ui.dp(this,16),Ui.dp(this,10));if(back!=null){TextView b=Ui.button(this,"‹",false,back);b.setContentDescription("Назад");top.addView(b,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));}TextView heading=Ui.text(this,title,21,Ui.TEXT,true);heading.setPadding(Ui.dp(this,back==null?0:10),0,0,0);heading.setMaxLines(2);top.addView(heading,new LinearLayout.LayoutParams(0,-2,1));TextView connection=Ui.button(this,"WEB",false,this::info);connection.setTextColor(Ui.BLUE);connection.setContentDescription("О способах без токена");top.addView(connection);root.addView(top);}
    private LinearLayout scroll(){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);body=Ui.column(this);body.setPadding(Ui.dp(this,16),Ui.dp(this,8),Ui.dp(this,16),Ui.dp(this,24));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));return body;}
    private void showCatalog(){cancel();screen="catalog";shell("YORU VK Web",null);LinearLayout head=Ui.column(this);head.setPadding(Ui.dp(this,16),0,Ui.dp(this,16),0);head.addView(Ui.text(this,"SHIKIMORI × ВК · отдельный прототип",11,Ui.ACCENT,true));Ui.gap(head,9);head.addView(Ui.text(this,"Найди историю. Выбери серию.",22,Ui.TEXT,true));Ui.gap(head,6);head.addView(Ui.text(this,"Обложки и названия — Shikimori. Выбери аниме и нужную серию.",12,Ui.MUTED,false));Ui.gap(head,14);LinearLayout row=Ui.row(this);catalogInput=Ui.input(this,"Название аниме",false);catalogInput.setText(catalogQuery);catalogInput.setFilters(new InputFilter[]{new InputFilter.LengthFilter(150)});catalogInput.setImeOptions(EditorInfo.IME_ACTION_SEARCH);row.addView(catalogInput,new LinearLayout.LayoutParams(0,-2,1));TextView find=Ui.button(this,"Найти",true,()->{hideKeyboard();loadCatalog(true);});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-2,-2);rp.leftMargin=Ui.dp(this,8);row.addView(find,rp);head.addView(row);Ui.gap(head,8);LinearLayout shortcuts=Ui.row(this);shortcuts.addView(Ui.button(this,"Популярное",false,()->{catalogInput.setText("");loadCatalog(true);}));TextView sao=Ui.button(this,"Мастера меча онлайн",false,()->{catalogInput.setText("Мастера меча онлайн");loadCatalog(true);});LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,-2,1);sp.leftMargin=Ui.dp(this,8);shortcuts.addView(sao,sp);head.addView(shortcuts);status=Ui.text(this,catalog.isEmpty()?"Каталог Shikimori":"Shikimori · показано "+catalog.size(),12,Ui.MUTED,false);status.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,10));head.addView(status);root.addView(head);grid=new GridView(this);grid.setNumColumns(getResources().getConfiguration().screenWidthDp>=650?3:2);grid.setHorizontalSpacing(Ui.dp(this,10));grid.setVerticalSpacing(Ui.dp(this,12));grid.setPadding(Ui.dp(this,16),0,Ui.dp(this,16),Ui.dp(this,12));grid.setClipToPadding(false);grid.setAdapter(new CatalogAdapter());root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));more=Ui.button(this,"Ещё аниме",false,()->loadCatalog(false));root.addView(more,new LinearLayout.LayoutParams(-1,-2));catalogInput.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH){hideKeyboard();loadCatalog(true);return true;}return false;});catalogInput.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){cancel();catalogQuery=s.toString().trim();status.setText("Поиск Shikimori…");more.setEnabled(false);handler.removeCallbacks(autoSearch);handler.postDelayed(autoSearch,700);}public void afterTextChanged(Editable e){}});}
    private void loadCatalog(boolean reset){if(!screen.equals("catalog"))return;if(loading&&!reset)return;cancel();loading=true;catalogQuery=catalogInput.getText().toString().trim();boolean replace=reset||!catalogQuery.equals(loadedCatalogQuery);int target=replace?1:catalogPage+1;String query=catalogQuery;int gen=ticket;status.setText("Загружаем Shikimori…");more.setEnabled(false);work=app.run(()->Api.catalog(query,target),(rows,error)->{if(gen!=ticket||isFinishing())return;loading=false;more.setEnabled(true);if(error!=null){status.setText(Ui.error(error)+" Нажмите здесь для повтора.");status.setOnClickListener(v->loadCatalog(reset));return;}status.setOnClickListener(null);if(replace)catalog.clear();loadedCatalogQuery=query;HashSet<Long> ids=new HashSet<>();for(Models.Anime a:catalog)ids.add(a.id);for(Models.Anime a:rows)if(ids.add(a.id))catalog.add(a);catalogPage=target;((BaseAdapter)grid.getAdapter()).notifyDataSetChanged();status.setText(catalog.isEmpty()?"Ничего не найдено. Попробуйте русское или оригинальное название.":"Shikimori · показано "+catalog.size());more.setVisibility(rows.size()<20?View.GONE:View.VISIBLE);});}
    private final class CatalogAdapter extends BaseAdapter {
        public int getCount(){return catalog.size();}public Object getItem(int i){return catalog.get(i);}public long getItemId(int i){return catalog.get(i).id;}
        public View getView(int i,View old,ViewGroup parent){CardHolder holder;if(old==null){holder=new CardHolder();LinearLayout c=Ui.column(MainActivity.this);holder.image=Ui.image(MainActivity.this,-1,240);int cols=getResources().getConfiguration().screenWidthDp>=650?3:2;holder.image.getLayoutParams().height=Ui.dp(MainActivity.this,(getResources().getConfiguration().screenWidthDp/cols-25)*3/2);c.addView(holder.image);Ui.gap(c,8);holder.title=Ui.text(MainActivity.this,"",13,Ui.TEXT,true);holder.title.setMaxLines(2);holder.title.setEllipsize(TextUtils.TruncateAt.END);c.addView(holder.title,new LinearLayout.LayoutParams(-1,Ui.dp(MainActivity.this,44)));holder.meta=Ui.text(MainActivity.this,"",10,Ui.MUTED,false);holder.meta.setSingleLine();holder.meta.setEllipsize(TextUtils.TruncateAt.END);c.addView(holder.meta);c.setTag(holder);old=c;}else holder=(CardHolder)old.getTag();Models.Anime a=catalog.get(i);holder.title.setText(a.title);holder.meta.setText(a.meta());Ui.load(holder.image,a.poster);old.setContentDescription(a.title+". "+a.meta());old.setOnClickListener(v->openAnime(a));return old;}
    }
    private static final class CardHolder {ImageView image;TextView title,meta;}
    private void openAnime(Models.Anime anime){cancel();current=anime;season=SearchRules.season(anime.title+" "+anime.original);episode=1;seasonDraft=String.valueOf(season);episodeDraft="1";voiceDraft="";drawAnime("Уточняем карточку Shikimori…");int gen=ticket;work=app.run(()->Api.details(anime.id),(a,e)->{if(gen!=ticket||isFinishing())return;if(e==null){current=a;drawAnime("");}else drawAnime("Карточка показана по каталогу. Подробности сейчас недоступны.");});}
    private void drawAnime(String note){screen="anime";shell("Карточка Shikimori",this::showCatalog);scroll();LinearLayout hero=Ui.row(this);hero.setGravity(Gravity.TOP);ImageView poster=Ui.image(this,112,164);hero.addView(poster);Ui.load(poster,current.poster);LinearLayout info=Ui.column(this);info.setPadding(Ui.dp(this,14),0,0,0);info.addView(Ui.text(this,current.title,21,Ui.TEXT,true));Ui.gap(info,8);info.addView(Ui.text(this,current.meta(),12,Ui.ACCENT,false));Ui.gap(info,8);info.addView(Ui.text(this,current.original,11,Ui.MUTED,false));hero.addView(info,new LinearLayout.LayoutParams(0,-2,1));body.addView(hero);Ui.gap(body,18);LinearLayout controls=Ui.card(this);controls.addView(Ui.text(this,"Какую серию ищем?",18,Ui.TEXT,true));Ui.gap(controls,8);controls.addView(Ui.text(this,current.movie()?"Фильм: поиск без номера сезона и серии.":"Сезоны в Shikimori — отдельные тайтлы. Проверь номер сезона для запроса ВК.",12,Ui.MUTED,false));LinearLayout numbers=Ui.row(this);EditText seasonInput=Ui.input(this,"Сезон",true),episodeInput=Ui.input(this,"Серия",true);seasonInput.setContentDescription("Номер сезона");episodeInput.setContentDescription("Номер серии");seasonInput.setText(seasonDraft);episodeInput.setText(episodeDraft);watchDraft(seasonInput,value->seasonDraft=value);watchDraft(episodeInput,value->episodeDraft=value);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,1);numbers.addView(seasonInput,np);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(0,-2,1);ep.leftMargin=Ui.dp(this,10);numbers.addView(episodeInput,ep);if(!current.movie()){Ui.gap(controls,10);controls.addView(Ui.text(this,"Сезон                         Серия",11,Ui.MUTED,false));controls.addView(numbers);}Ui.gap(controls,10);EditText voice=Ui.input(this,"Озвучка — необязательно",false);voice.setFilters(new InputFilter[]{new InputFilter.LengthFilter(60)});voice.setText(voiceDraft);watchDraft(voice,value->voiceDraft=value);controls.addView(voice);Ui.gap(controls,12);controls.addView(Ui.button(this,"Смотреть · найти видео ВК",true,()->{try{season=Integer.parseInt(seasonInput.getText().toString());episode=Integer.parseInt(episodeInput.getText().toString());videoQuery=SearchRules.query(current.title,season,episode,current.movie(),voice.getText().toString());showMethods();}catch(Exception e){Ui.message(this,"Проверьте серию",e instanceof NumberFormatException?"Введите номер сезона и серии цифрами.":Ui.error(e));}}));body.addView(controls);Ui.gap(body,10);body.addView(Ui.text(this,"ВК ищет по тексту, а не по ID Shikimori. Совпадение сезона, серии и озвучки нужно проверить по результату.",12,Ui.MUTED,false));if(!note.isEmpty()){Ui.gap(body,10);body.addView(Ui.text(this,note,12,Ui.BLUE,false));}if(!current.genres.isEmpty()){Ui.gap(body,16);body.addView(Ui.text(this,current.genres,12,Ui.ACCENT,false));}Ui.gap(body,18);body.addView(Ui.text(this,"Об истории",18,Ui.TEXT,true));Ui.gap(body,9);CharSequence description=current.description.isEmpty()?"Описание пока недоступно.":Html.fromHtml(current.description,Html.FROM_HTML_MODE_COMPACT);body.addView(Ui.text(this,description.toString(),14,Ui.MUTED,false));Ui.gap(body,18);body.addView(Ui.button(this,"Другие сезоны и связанные тайтлы",false,this::related));}
    private void related(){cancel();int gen=ticket;long id=current.id;work=app.run(()->Api.related(id),(rows,error)->{if(gen!=ticket||isFinishing())return;if(error!=null){Ui.message(this,"Shikimori",Ui.error(error));return;}if(rows.isEmpty()){Ui.message(this,"Связанные тайтлы","Shikimori не вернул связанные аниме.");return;}String[] labels=new String[rows.size()];for(int i=0;i<rows.size();i++)labels[i]=rows.get(i).title+" · "+rows.get(i).meta();new AlertDialog.Builder(this).setTitle("Выберите отдельный сезон / тайтл").setItems(labels,(d,which)->openAnime(rows.get(which))).setNegativeButton("Назад",null).show();});}
    private void showMethods(){cancel();screen="methods";shell("Выберите способ",()->{cancel();drawAnime("");});scroll();body.addView(Ui.text(this,current.title,21,Ui.TEXT,true));Ui.gap(body,8);body.addView(Ui.text(this,"Токен не нужен. Результаты и просмотр открываются на страницах сайтов; ВК может попросить обычный вход.",13,Ui.MUTED,false));Ui.gap(body,14);vkInput=Ui.input(this,"Запрос — можно изменить",false);vkInput.setSingleLine(false);vkInput.setMaxLines(3);vkInput.setFilters(new InputFilter[]{new InputFilter.LengthFilter(250)});vkInput.setText(videoQuery);body.addView(vkInput);Ui.gap(body,10);LinearLayout aliases=Ui.row(this);aliases.addView(Ui.button(this,"Русское",false,()->vkInput.setText(SearchRules.query(current.title,season,episode,current.movie(),voiceDraft))));if(!current.original.isEmpty()){TextView alt=Ui.button(this,"Оригинальное",false,()->vkInput.setText(SearchRules.query(current.original,season,episode,current.movie(),voiceDraft)));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,-2,1);ap.leftMargin=Ui.dp(this,8);aliases.addView(alt,ap);}body.addView(aliases);String[] descriptions={"Основной способ: режим ПК. В публичной проверке получена выдача по названию аниме без входа. Страницу можно масштабировать.","Прямой мобильный адрес с правильной кодировкой русского запроса. Тот же сервис ВК; если загрузка зависла, выберите версию ПК.","Ищет только проиндексированные публичные страницы VK. Закрытые и удалённые видео не открывает.","Другой поисковый индекс публичных ссылок VK. Выдача может отличаться от Яндекса."};for(int i=0;i<WebRoutes.LABELS.length;i++){final int method=i;Ui.gap(body,16);LinearLayout box=Ui.card(this);box.addView(Ui.text(this,WebRoutes.LABELS[i],16,Ui.TEXT,true));Ui.gap(box,7);box.addView(Ui.text(this,descriptions[i],12,Ui.MUTED,false));Ui.gap(box,10);LinearLayout actions=Ui.row(this);actions.addView(Ui.button(this,"В приложении",true,()->openMethod(method,false)),new LinearLayout.LayoutParams(0,-2,1));TextView browser=Ui.button(this,"Браузер",false,()->openMethod(method,true));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,-2,1);bp.leftMargin=Ui.dp(this,8);actions.addView(browser,bp);box.addView(actions);body.addView(box);}Ui.gap(body,18);body.addView(Ui.button(this,"Есть ссылка на видео · открыть",false,this::linkDialog));Ui.gap(body,12);body.addView(Ui.text(this,"Нет автоматического подтверждения серии, обхода CAPTCHA или снятия ограничений доступа. Если сайт требует приложение или не работает в WebView — используйте «Браузер».",12,Ui.MUTED,false));}
    private void openMethod(int method,boolean external){try{videoQuery=vkInput.getText().toString().trim();String url=WebRoutes.search(method,videoQuery);if(method<2&&!external){Intent search=new Intent(this,VideoSearchActivity.class);search.putExtra("query",videoQuery);search.putExtra("mobile",method==1);startActivity(search);}else openPage(url,external,method==0);}catch(Exception e){Ui.message(this,"Запрос",e.getMessage());}}
    private void openPage(String url,boolean external){openPage(url,external,false);}
    private void openPage(String url,boolean external,boolean desktop){if(!WebRoutes.allowedPage(url)){Ui.message(this,"Адрес","Этот сайт не разрешён во встроенном просмотре.");return;}hideKeyboard();if(external){try{Intent i=new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(WebRoutes.modeUrl(url,false)));i.addCategory(Intent.CATEGORY_BROWSABLE);startActivity(Intent.createChooser(i,"Открыть сайт поиска"));}catch(Exception e){Ui.message(this,"Браузер","Не найдено приложение для HTTPS-ссылок. Используйте «В приложении».");}}else{Intent i=new Intent(this,WebActivity.class);i.putExtra("url",url);i.putExtra("query",videoQuery);i.putExtra("desktop",desktop);startActivity(i);}}
    private void linkDialog(){EditText input=Ui.input(this,"https://vkvideo.ru/video…",false);input.setSaveEnabled(false);input.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(8192)});LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,18),0,Ui.dp(this,18),0);box.addView(Ui.text(this,"Прямая ссылка VK или ссылка официального встроенного плеера. Без токена. Встраивание может быть запрещено владельцем ролика.",12,Ui.MUTED,false));Ui.gap(box,10);box.addView(input);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Открыть конкретное видео").setView(box).setPositiveButton("Страница ВК",null).setNeutralButton("Веб-плеер",null).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String url=WebRoutes.videoLink(input.getText().toString());input.setText("");dialog.dismiss();openPage(url,false);}catch(Exception e){input.setError(e.getMessage());}});dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{try{String url=WebRoutes.embed(input.getText().toString());input.setText("");dialog.dismiss();openPage(url,false);}catch(Exception e){input.setError(e.getMessage());}});});dialog.show();}
    private void info(){new AlertDialog.Builder(this).setTitle("YORU VK Web 0.2.1").setMessage("Отдельный веб-прототип. Kate Mobile, ручные токены и старые методы VK API удалены.\n\nShikimori даёт карточки. Четыре маршрута открывают поиск VK или публичных ссылок; Google/Яндекс получают текст запроса. Сайты могут требовать вход или CAPTCHA.\n\nВнутри приложения — стандартный WebView, без чтения паролей/cookies, без JavaScript-моста и извлечения закрытых потоков. На странице всегда виден домен. Веб-сессия отдельная от браузера и основной YORU; её можно удалить в меню веб-экрана.\n\nЭто не нативный плеер YORU. Основная YORU 4.19.1 не изменялась.").setPositiveButton("Понятно",null).setNeutralButton("Открыть ссылку",(d,w)->linkDialog()).show();}
    private void watchDraft(EditText input,java.util.function.Consumer<String> update){input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){update.accept(s.toString());}public void afterTextChanged(Editable e){}});}
    private void hideKeyboard(){View focus=getCurrentFocus();if(focus!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(focus.getWindowToken(),0);}
    @Override public void onBackPressed(){if(screen.equals("methods")){cancel();drawAnime("");}else if(screen.equals("anime"))showCatalog();else super.onBackPressed();}
    @Override protected void onDestroy(){cancel();super.onDestroy();}
}
